import React, { useState } from 'react';
import justEmptyPage from './listRendering/just-empty-page.jsx';
import mapingArrayToElements from './listRendering/mapping-an-array-to-elements.jsx';
import creatingAInstance from './theInstance/creating-a-instance.jsx';
import dataAndMethods from './theInstance/data-and-methods.jsx';
import lifecycleHooks from './theInstance/instance-lifecycle-hooks.jsx';
import './tabs.css';

const Tabs = () => {
  const [activeTab, setActiveTab] = useState('tabs')
  return (
    <div className="tabsContainer">
        <ul className="tabs">
            <li onClick={() => setActiveTab('justEmptyPage')}>Just Empty Page</li>
            <li onClick={() => setActiveTab('mapingArrayToElements')}>Mapping an Array to Elements</li>
            <li onClick={() => setActiveTab('creatingAInstance')}>Creating a Instance</li>
            <li onClick={() => setActiveTab('dataAndMethods')}>Data and Methods</li>
            <li onClick={() => setActiveTab('lifecycleHooks')}>Lifecycle Hooks</li>
        </ul>
        {activeTab === 'justEmptyPage' && <justEmptyPage />}
        {activeTab === 'mapingArrayToElements' && <mapingArrayToElements />}
        {activeTab === 'creatingAInstance' && <creatingAInstance />}
        {activeTab === 'dataAndMethods' && <dataAndMethods />}
        {activeTab === 'lifecycleHooks' && <lifecycleHooks />}
    </div>
  )
}

export default Tabs
